#include <iostream>
#include <string_view>
std::string_view choose(std::string_view format, int pages) {
    // Mandatory validation is independent of the selected desk.
    if (pages < 1 || pages > 1000) return "rejected";
    if (format == "label") return "label desk";
    if (format == "report") return "general desk";
    return "unhandled";
}
int main() {
    std::cout << choose("label", 2) << '\n';
    std::cout << choose("report", 6) << '\n';
    std::cout << choose("archive", 1) << '\n';
    std::cout << choose("label", 0) << '\n';
}

#include <iostream>
#include <optional>
#include <string>
#include <vector>
using Reply = std::optional<std::string>;
std::string first_answer(const std::vector<Reply>& replies) {
    for (const auto& reply : replies) {
        if (reply) return *reply;
    }
    return "unhandled";
}
std::string last_answer(const std::vector<Reply>& replies) {
    std::string result = "unhandled";
    for (const auto& reply : replies) {
        if (reply) result = *reply; // Intentional policy change.
    }
    return result;
}
int main() {
    // Precomputed replies isolate the stopping rule from handler code.
    const std::vector<Reply> replies{"label desk", "general desk"};
    std::cout << "first=" << first_answer(replies) << '\n';
    std::cout << "last=" << last_answer(replies) << '\n';
}
